<?php
namespace LST_SEO;
if (!defined('ABSPATH')) { exit; }
final class Admin {
    const SLUG='leadstart-seo';
    public static function boot(): void {
        add_action('admin_enqueue_scripts',[self::class,'assets']); add_action('admin_post_lst_seo',[self::class,'handle']);
        add_action('admin_init',[self::class,'bulk_hooks']);
        add_filter('plugin_action_links_'.plugin_basename(FILE),[self::class,'action_links']);
    }
    public static function tabs(): array { return ['dashboard'=>'Dashboard','indexing'=>'Instant Indexing','analysis'=>'SEO Analysis','analytics'=>'Analytics','schema'=>'Schema','geo'=>'GEO','ai'=>'Content AI','history'=>'History','settings'=>'Settings']; }
    public static function url(string $tab='dashboard'): string { return admin_url('admin.php?page='.self::SLUG.($tab==='dashboard'?'':'-'.$tab)); }
    public static function menu(): void {
        $dashboard=static function () { self::page('dashboard'); };
        add_menu_page('Leadstart SEO','Leadstart SEO','manage_options',self::SLUG,$dashboard,'dashicons-search',81);
        foreach (self::tabs() as $k=>$label) {
            $callback=$k==='dashboard'?$dashboard:static function () use ($k) { self::page($k); };
            add_submenu_page(self::SLUG,$label,$label,'manage_options',$k==='dashboard'?self::SLUG:self::SLUG.'-'.$k,$callback);
        }
    }
    public static function action_links(array $links): array {
        if (!current_user_can('manage_options')) { return $links; }
        $url=menu_page_url(self::SLUG.'-settings',false);
        if ($url) { array_unshift($links,'<a href="'.esc_url($url).'">'.esc_html__('Settings','leadstart-seo').'</a>'); }
        return $links;
    }
    public static function assets(string $hook): void { if (str_contains($hook,'leadstart-seo')) { wp_enqueue_style('lst-seo-admin',plugins_url('assets/admin.css',FILE),[],VERSION); } }
    private static function text(string $key,string $default=''): string {
        check_admin_referer('lst_seo_admin','lst_seo_admin_nonce');
        return isset($_POST[$key]) && is_string($_POST[$key])?sanitize_text_field(wp_unslash($_POST[$key])):$default;
    }
    private static function textarea(string $key): string {
        check_admin_referer('lst_seo_admin','lst_seo_admin_nonce');
        return isset($_POST[$key]) && is_string($_POST[$key])?sanitize_textarea_field(wp_unslash($_POST[$key])):'';
    }
    private static function google_input() {
        check_admin_referer('lst_seo_admin','lst_seo_admin_nonce');
        if (!isset($_POST['google_json']) || !is_string($_POST['google_json'])) { return ''; }
        // JSON and PEM must be decoded and validated before re-encoding; generic text sanitization would corrupt keys.
        $raw=trim(wp_unslash($_POST['google_json'])); // phpcs:ignore WordPress.Security.ValidatedSanitizedInput.InputNotSanitized -- Config::google_json() validates JSON, allowlists the OAuth endpoint, sanitizes the email and normalizes the RSA key with OpenSSL before re-encoding. Text sanitization would corrupt structured credentials.
        if ($raw==='') { return ''; }
        $validated=Config::google_json($raw);
        if (is_wp_error($validated)) { return $validated; }
        $json=wp_json_encode($validated,JSON_UNESCAPED_SLASHES);
        return is_string($json)?$json:new \WP_Error('credential','Credential encoding failed.');
    }
    private static function bing_input() {
        check_admin_referer('lst_seo_admin','lst_seo_admin_nonce');
        if (!isset($_POST['bing_key']) || !is_string($_POST['bing_key'])) { return ''; }
        $key=sanitize_text_field(wp_unslash($_POST['bing_key']));
        if (($key==='' && !empty($_POST['bing_key'])) || ($key!=='' && !preg_match('/^[A-Za-z0-9_-]{8,256}$/D',$key))) { return new \WP_Error('credential','Invalid Bing key format.'); }
        return $key;
    }
    private static function mapping_input(string $key) {
        check_admin_referer('lst_seo_admin','lst_seo_admin_nonce');
        // Mappings accept only simple ASCII public meta keys, not rich JSON content.
        return Schema::mapping(isset($_POST[$key]) && is_string($_POST[$key])?sanitize_textarea_field(wp_unslash($_POST[$key])):'');
    }
    private static function urls_input() {
        check_admin_referer('lst_seo_admin','lst_seo_admin_nonce');
        // Split first: text sanitizers remove valid percent escapes from URLs.
        // Config::url() validates each original URL and calls esc_url_raw() before enqueueing.
        $raw=isset($_POST['urls']) && is_string($_POST['urls'])?wp_unslash($_POST['urls']):''; // phpcs:ignore WordPress.Security.ValidatedSanitizedInput.InputNotSanitized -- The size- and count-limited list is split into individual URLs; Config::url() validates same-site HTTP(S) URLs and applies esc_url_raw() before any submission is queued. Preserve encoded URL characters.
        if (strlen($raw)>210000) { return new \WP_Error('urls','Request too large.'); }
        $urls=array_values(array_unique(array_filter(array_map('trim',preg_split('/\R/',$raw)?:[]))));
        if (!$urls || count($urls)>100) { return new \WP_Error('urls','Enter 1–100 URLs.'); }
        $valid=[]; $invalid=0;
        foreach ($urls as $url) { $clean=Config::url($url); if ($clean==='') { $invalid++; } else { $valid[]=$clean; } }
        return ['urls'=>$valid,'invalid'=>$invalid];
    }
    private static function checked_input(string $key): bool { return self::text($key)==='1'; }
    private static function choices_input(string $key,array $allowed): array {
        check_admin_referer('lst_seo_admin','lst_seo_admin_nonce');
        if (!isset($_POST[$key]) || !is_array($_POST[$key])) { return []; }
        // Unslash and sanitize the submitted array at the boundary; discard non-string shapes.
        $values=map_deep(wp_unslash($_POST[$key]),'sanitize_text_field');
        $values=array_filter($values,'is_string');
        return array_values(array_intersect($allowed,$values));
    }
    private static function history_page(): int {
        if (!isset($_GET['pagenum'])) { return 1; }
        check_admin_referer('lst_seo_history_page','lst_seo_history_nonce');
        return is_string($_GET['pagenum'])?max(1,min(10000,absint(wp_unslash($_GET['pagenum'])))):1;
    }
    private static function history_url(int $page): string {
        return add_query_arg(['pagenum'=>$page,'lst_seo_history_nonce'=>wp_create_nonce('lst_seo_history_page')],self::url('history'));
    }
    private static function analysis_id(): int {
        if (!isset($_GET['post_id'])) { return 0; }
        check_admin_referer('lst_seo_analyze','lst_seo_analysis_nonce');
        return is_string($_GET['post_id'])?absint(wp_unslash($_GET['post_id'])):0;
    }
    private static function form(string $op,string $tab): void { echo '<form method="post" action="'.esc_url(admin_url('admin-post.php')).'"><input type="hidden" name="action" value="lst_seo"><input type="hidden" name="op" value="'.esc_attr($op).'"><input type="hidden" name="tab" value="'.esc_attr($tab).'">'; wp_nonce_field('lst_seo_'.$op); wp_nonce_field('lst_seo_admin','lst_seo_admin_nonce',false); }
    private static function field(string $name,string $label,string $value='',string $type='text'): void { echo '<p><label for="lst-'.esc_attr($name).'">'.esc_html($label).'</label><br><input class="regular-text" id="lst-'.esc_attr($name).'" type="'.esc_attr($type).'" name="'.esc_attr($name).'" value="'.esc_attr($value).'"></p>'; }
    private static function check(string $name,string $label,bool $checked=false): void { echo '<p><label><input type="checkbox" name="'.esc_attr($name).'" value="1" '.checked($checked,true,false).'> '.esc_html($label).'</label></p>'; }
    private static function select(string $name,string $label,array $choices,string $value='',string $element_id=''): void { $element_id=$element_id?:$name; echo '<p><label for="lst-'.esc_attr($element_id).'">'.esc_html($label).'</label><br><select id="lst-'.esc_attr($element_id).'" name="'.esc_attr($name).'">'; foreach ($choices as $k=>$v) { echo '<option value="'.esc_attr((string)$k).'" '.selected((string)$k,$value,false).'>'.esc_html($v).'</option>'; } echo '</select></p>'; }
    private static function end(string $label): void { submit_button($label); echo '</form>'; }
    private static function notice(string $message,string $type='info'): void { echo '<div class="notice notice-'.esc_attr($type).' inline"><p>'.esc_html($message).'</p></div>'; }
    private static function flash(string $tab,string $message,string $type='success',$data=null): void { set_transient('lst_seo_flash_'.get_current_user_id(),['message'=>$message,'type'=>$type,'data'=>$data],120); wp_safe_redirect(self::url($tab)); exit; }
    private static function post_types(): array { $types=get_post_types(['public'=>true],'objects'); unset($types['attachment']); return $types; }
    public static function page(string $tab='dashboard'): void {
        if (!current_user_can('manage_options')) { wp_die('Access denied.'); }
        if (!isset(self::tabs()[$tab])) { $tab='dashboard'; }
        $flash=get_transient('lst_seo_flash_'.get_current_user_id()); delete_transient('lst_seo_flash_'.get_current_user_id());
        echo '<div class="wrap lst-seo"><h1>'.esc_html(self::tabs()[$tab]).' <span class="lst-version">Leadstart SEO '.esc_html(VERSION).'</span></h1><nav class="nav-tab-wrapper" aria-label="Leadstart SEO">'; foreach (self::tabs() as $k=>$name) { echo '<a class="nav-tab '.($k===$tab?'nav-tab-active':'').'" href="'.esc_url(self::url($k)).'">'.esc_html($name).'</a>'; } echo '</nav>';
        if (is_array($flash)) { self::notice($flash['message'],$flash['type']); if (is_array($flash['data']) && isset($flash['data']['headers'],$flash['data']['rows'])) { self::table($flash['data']['headers'],$flash['data']['rows']); } elseif (is_string($flash['data'])) { echo '<div class="lst-panel"><h2>Result</h2><textarea class="large-text" rows="12" readonly>'.esc_textarea($flash['data']).'</textarea></div>'; } }
        switch ($tab) { case 'settings': self::settings(); break; case 'indexing': self::indexing(); break; case 'history': self::history(); break; case 'analysis': self::analysis(); break; case 'schema': self::schema(); break; case 'geo': self::geo(); break; case 'analytics': self::analytics(); break; case 'ai': self::ai(); break; default: self::dashboard(); }
        echo '</div>';
    }
    private static function dashboard(): void { $s=Config::get(); $q=Queue::quota(); echo '<div class="lst-grid">'; foreach (['Google API'=>Config::secret('google_json')?'Credentials configured':'Not configured','IndexNow'=>$s['indexnow']?'Enabled':'Disabled','Bing legacy fallback'=>$s['bing_fallback']?'Enabled':'Disabled','Google daily local attempts'=>$q['used'].' / '.$s['google_limit'],'Analytics'=>'Reporting only — no tracking script','GEO / llms.txt'=>$s['geo']?(GEO::conflict()?'Another generator detected':'Enabled'):'Disabled','Content AI'=>$s['ai']?'Enabled — WordPress Connectors':'Disabled'] as $label=>$v) { echo '<div class="lst-panel"><h2>'.esc_html($label).'</h2><p>'.esc_html($v).'</p></div>'; } echo '</div><p>Submission acceptance is not proof of indexing. Configure eligible post types and credentials before enabling automatic notifications.</p>'; if (SEO::competitor()) { self::notice('Another SEO provider is detected. Leadstart metadata and overlapping schema output are suppressed.','warning'); } if (defined('GOOGLESITEKIT_VERSION')) { self::notice('Google Site Kit detected. Leadstart does not inject analytics tags or change Site Kit settings.'); } }
    private static function settings(): void {
        $s=Config::get(); echo '<div class="lst-panel"><h2>Google and Bing credentials</h2><p>Keys are write-only, encrypted using WordPress salts when stored in the database. Rotating salts requires re-entering credentials. A compromised server can still access secrets. Constants override database storage.</p>'; self::form('credentials','settings');
        echo '<p>Google service account: '.esc_html(Config::secret('google_json')?'Configured':'Not configured').'</p><label for="lst-google-json">New service account JSON (paste; never displayed again)</label><textarea id="lst-google-json" name="google_json" class="large-text" rows="5" autocomplete="off" spellcheck="false"></textarea>'; self::check('clear_google','Remove saved Google credential'); self::field('bing_key','New Bing Webmaster API key (blank keeps current)','','password'); self::check('clear_bing','Remove saved Bing credential'); self::end('Save credentials');
        echo '<h3>Connection tests</h3><p>Save credentials and settings before testing. Tests use saved configuration. Google OAuth does not prove indexing permission; IndexNow checks the public key file without submitting URLs.</p>';
        foreach (['google'=>'Test Google service account JSON','indexnow'=>'Test IndexNow key file','bing'=>'Test Bing quota','gsc'=>'Test Search Console','ga'=>'Test GA4'] as $test=>$label) { self::test_form($test,'settings',$label); }
        self::test_form('ai','settings','Test Content AI'); echo '</div><div class="lst-panel"><h2>Indexing and reporting</h2>'; self::form('settings','settings'); self::check('indexnow','Enable IndexNow',$s['indexnow']); self::field('index_key','IndexNow key (blank generates a key when enabled)',$s['index_key']); self::field('key_path','Optional externally hosted key path relative to site root',$s['key_path']); if ($s['index_key']) { echo '<p>Key URL: <code>'.esc_html(API::key_url()).'</code>. If your server does not route .txt requests to WordPress, place the key in a real text file.</p>'; } self::check('bing_fallback','Enable legacy Bing URL Submission (and fallback on selected IndexNow errors)',$s['bing_fallback']); self::field('google_limit','Local Google daily notification budget',(string)$s['google_limit'],'number');
        echo '<h3>Automatic submissions (disabled until selected)</h3><table class="widefat striped"><thead><tr><th>Post type</th><th>Google (requires per-post eligibility)</th><th>IndexNow</th></tr></thead><tbody>'; foreach (self::post_types() as $type=>$obj) { echo '<tr><td>'.esc_html($obj->label).'</td>'; foreach (['google_auto','indexnow_auto'] as $k) { echo '<td><input aria-label="'.esc_attr($obj->label.' '.$k).'" type="checkbox" name="'.esc_attr($k).'[]" value="'.esc_attr($type).'" '.checked(in_array($type,$s[$k],true),true,false).'></td>'; } echo '</tr>'; } echo '</tbody></table>'; self::field('gsc_property','Search Console property (exact home URL or sc-domain:host)',$s['gsc_property']); self::field('ga_property','GA4 numeric property ID',$s['ga_property']); self::field('report_start','All Time report start date (optional override)',$s['report_start'],'date'); echo '<p class="description">Leave blank to use the first published post, page or public custom post type. Current All Time start: '.esc_html(Reports::all_start()).'. Provider data availability may be shorter.</p>'; self::check('meta','Enable SEO metadata output (suppressed for detected SEO plugins)',$s['meta']); self::check('use_excerpt','Use saved excerpts for SEO descriptions when no custom description is set',$s['use_excerpt']); echo '<p class="description">If an excerpt is empty, SEO can generate a short description from saved content. GEO never uses that content fallback. Turn this option off for manual descriptions only.</p><h3>Excerpt support by post type</h3><p>Selected public post types get the native WordPress excerpt field if they do not already support it. Unchecking does not remove support registered by WordPress, your theme or another plugin.</p>'; foreach (GEO::types() as $type=>$obj) { echo '<p><label><input type="checkbox" name="excerpt_types[]" value="'.esc_attr($type).'" '.checked(SEO::excerpt_selected($type,$s),true,false).'> '.esc_html($obj->label).'</label></p>'; } self::check('schema','Enable JSON-LD output (suppressed for detected overlapping plugins)',$s['schema']); self::check('ai','Enable user-initiated Content AI',$s['ai']); self::select('ai_provider','Content AI provider',AI::choices($s['ai_provider']),$s['ai_provider']); echo '<p class="description">Model: automatic selection by WordPress. Configure credentials in WordPress Connectors.</p>'; self::check('ai_fallback','Allow one fallback to another configured provider after authentication, billing, permission or quota rejection (explicit provider only)',!empty($s['ai_fallback'])); self::check('purge','Delete Leadstart-owned settings, queue and post metadata on uninstall',$s['purge']); self::end('Save settings'); echo '</div>';
    }
    private static function geo(): void {
        $s=Config::get();
        echo '<div class="lst-panel"><h2>'.esc_html__('Generative Engine Optimization (GEO)','leadstart-seo').'</h2><p>'.esc_html__('Publish a curated Markdown index of public content at llms.txt. This is a voluntary proposal, not an indexing or AI citation guarantee. No content is sent to AI providers by this feature.','leadstart-seo').'</p>';
        if (GEO::conflict()) { self::notice(__('Another llms.txt generator is detected. Disable its output before using Leadstart GEO.','leadstart-seo'),'warning'); }
        if (GEO::restricted_site()) { self::notice(__('A known access-control plugin is active. GEO is blocked until an integrator verifies anonymous access and implements the documented filters.','leadstart-seo'),'warning'); }
        if (!get_option('blog_public')) { self::notice(__('Search engine visibility is disabled; Leadstart will not serve the document.','leadstart-seo'),'warning'); }
        echo '<p><strong>'.esc_html__('Public URL','leadstart-seo').':</strong> <a href="'.esc_url(GEO::url()).'" target="_blank" rel="noopener noreferrer">'.esc_html(GEO::url()).'</a></p>';
        self::form('geo','geo'); self::check('geo',__('Enable llms.txt','leadstart-seo'),(bool)$s['geo']); self::field('geo_title',__('Site title (blank uses WordPress site name)','leadstart-seo'),$s['geo_title']);
        echo '<p><label for="lst-geo-description">'.esc_html__('Site summary (blank uses the site tagline)','leadstart-seo').'</label><br><textarea class="large-text" rows="3" maxlength="500" id="lst-geo-description" name="geo_description">'.esc_textarea($s['geo_description']).'</textarea></p><h3>'.esc_html__('Include public post types','leadstart-seo').'</h3>';
        foreach (GEO::types() as $type=>$obj) { echo '<p><label><input type="checkbox" name="geo_types[]" value="'.esc_attr($type).'" '.checked(in_array($type,$s['geo_types'],true),true,false).'> '.esc_html($obj->label).'</label></p>'; }
        self::field('geo_limit',__('Maximum links per type (1–200)','leadstart-seo'),(string)$s['geo_limit'],'number');
        self::check('geo_navigation',__('Prioritize linked navigation pages and posts','leadstart-seo'),(bool)$s['geo_navigation']);
        self::check('geo_cache',__('Cache candidate IDs locally for up to 15 minutes','leadstart-seo'),(bool)$s['geo_cache']);
        echo '<p class="description">'.esc_html__('Pinned posts are prioritized before navigation and recent content. Private, excluded and noindex content is never included by a priority setting. Cached IDs are rechecked on every request; descriptions and documents are not cached.','leadstart-seo').'</p><h3>'.esc_html__('Optional AI crawler restrictions','leadstart-seo').'</h3><p>'.esc_html__('Unselected crawlers retain the existing site policy. Selected crawlers receive Disallow: / only if they have no existing named rule. Static robots.txt files take precedence. These are voluntary instructions, not access controls. Applies only to root sites.','leadstart-seo').'</p>';
        foreach (GEO::bots() as $bot=>$label) { echo '<p><label><input type="checkbox" name="geo_bots[]" value="'.esc_attr($bot).'" '.checked(in_array($bot,(array)$s['geo_bots'],true),true,false).'> '.esc_html($label.' ('.$bot.')').'</label></p>'; }
        echo '<p class="description">'.esc_html__('Up to 1,000 links overall. Only public published, locally indexable content is listed; use the editor exclusion checkbox for protected or member-only content. Summaries use saved SEO descriptions or excerpts, never the full post body. Verify access rules before enabling.','leadstart-seo').'</p>';
        self::end(__('Save GEO settings','leadstart-seo')); self::form('geo_clear','geo'); self::end(__('Clear GEO candidate cache','leadstart-seo')); echo '</div><div class="lst-panel"><h2>'.esc_html__('Serving and compatibility','leadstart-seo').'</h2><p>'.esc_html__('The document is rendered from current public content on request. Candidate IDs may be cached briefly; access checks and summaries are always fresh. Your web server must route llms.txt to WordPress. An existing static file or another generator may take precedence; this plugin never overwrites it.','leadstart-seo').'</p><p><a href="https://llmstxt.org/" target="_blank" rel="noopener noreferrer">'.esc_html__('Read the llms.txt proposal','leadstart-seo').'</a></p></div>';
    }
    private static function indexing(): void { echo '<div class="lst-panel"><p>One same-site URL per line, up to 100 per submission. Google updates require an eligible public post marked in its Leadstart SEO editor panel. IndexNow is for public changed URLs. Legacy Bing fallback is optional and does not bypass rate limits.</p>'; self::form('submit','indexing'); self::select('provider','Provider',['google'=>'Google Indexing / Inspection','indexnow'=>'IndexNow (optional Bing fallback)','bing'=>'Bing legacy direct']); self::select('request','Action',['update'=>'Publish / update','delete'=>'Notify removed URL','metadata'=>'Google notification metadata','inspect'=>'Google URL Inspection']); echo '<p><label for="lst-urls">URLs</label><br><textarea id="lst-urls" class="large-text" name="urls" rows="8" required></textarea></p>'; self::check('attest','For removed URLs: I verified removal/noindex and, for Google, prior eligibility. For unresolved IndexNow URLs: I verified public indexability.'); self::end('Queue URLs'); echo '</div>'; self::form('run','indexing'); self::end('Process next queue batch'); }
    private static function history(): void { $page=self::history_page(); $jobs=Queue::query(['numberposts'=>50,'offset'=>($page-1)*50]); echo '<p>Completed history is retained for approximately 30 days. Unknown delivery is not automatically retried. A manual retry may resend an already accepted notification; inspect provider status first.</p>'; self::form('run','history'); self::end('Process next batch'); if (get_option(Queue::LOCK)==='locked' && (int)get_option(Queue::LOCK_TIME,0)<=time()-900) { self::form('unlock','history'); self::end('Release stale worker lock (confirm no worker is running)'); } echo '<table class="widefat striped"><thead><tr><th>URL</th><th>Provider / action</th><th>Status</th><th>Response</th><th>Attempts</th><th>Created (UTC)</th><th>Actions</th></tr></thead><tbody>'; foreach ($jobs as $id) { $j=Queue::get($id); if (!$j) { continue; } echo '<tr><td class="lst-url">'.esc_html($j['url']).'</td><td>'.esc_html($j['provider'].' / '.$j['action']).'</td><td>'.esc_html($j['status']).'</td><td>'.esc_html($j['result']); if (!empty($j['details'])) { echo '<details><summary>Details</summary><pre>'.esc_html(wp_json_encode($j['details'],JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES)).'</pre></details>'; } echo '</td><td>'.esc_html((string)$j['attempts']).'</td><td>'.esc_html(gmdate('Y-m-d H:i',$j['created'])).'</td><td>'; if (in_array($j['status'],['failed','unknown'],true)) { self::form('retry','history'); echo '<input type="hidden" name="id" value="'.esc_attr((string)$id).'">'; submit_button('Retry','secondary','submit',false); echo '</form>'; } echo '</td></tr>'; } echo '</tbody></table><p>'; if ($page>1) { echo '<a class="button" href="'.esc_url(self::history_url($page-1)).'">Previous</a> '; } if (count($jobs)===50) { echo '<a class="button" href="'.esc_url(self::history_url($page+1)).'">Next</a>'; } echo '</p>'; }
    private static function analysis(): void { $id=self::analysis_id(); echo '<div class="lst-panel"><p>Local analysis of saved content. Scores are heuristics, not ranking scores. Editor analysis is also available on public post types.</p><form method="get"><input type="hidden" name="page" value="leadstart-seo-analysis">'; wp_nonce_field('lst_seo_analyze','lst_seo_analysis_nonce',false); self::field('post_id','Post ID',$id?(string)$id:'','number'); submit_button('Analyze'); echo '</form>'; if ($id && current_user_can('edit_post',$id) && ($p=get_post($id)) && $p->post_type!==Queue::TYPE) { echo '<h2>'.esc_html(get_the_title($p)).'</h2>'; SEO::render_analysis(SEO::analyze($p)); } echo '</div>'; }
    private static function schema(): void { $s=Config::get(); echo '<div class="lst-panel"><p>Map post types to JSON-LD types. Additional factual fields and per-post overrides are available in the editor. Invalid or incomplete required fields suppress output. Enable output separately in Settings.</p>'; self::form('schema','schema'); foreach (self::post_types() as $k=>$obj) { $choices=[''=>'None']+array_combine(Schema::types(),Schema::types()); self::select('schema_'.$k,$obj->label,$choices,$s['schema_map'][$k]??''); } echo '<h3>Public custom field mappings</h3><p>Optional JSON object per post type, e.g. {&quot;startDate&quot;:&quot;public_event_start&quot;}. Values are public post-meta keys. Only map fields intended for public disclosure. Protected or sensitive-looking keys are rejected. Nested structured data belongs in the per-post JSON editor.</p>'; foreach (self::post_types() as $k=>$obj) { echo '<p><label>'.esc_html($obj->label).' <textarea class="large-text" rows="2" name="'.esc_attr('fields_'.$k).'">'.esc_textarea(empty($s['field_map'][$k])?'':wp_json_encode($s['field_map'][$k])).'</textarea></label></p>'; } self::check('defaults','Use suggested mappings for post types instead of selected values'); self::end('Save schema mappings'); echo '</div>'; }
    private static function analytics(): void { echo '<div class="lst-panel"><p>Reporting only. No new analytics tags, tracking scripts or cookies. Site Kit can remain active. All Time is limited by each API and the configured report start; grouped reports return up to 50 rows.</p>'; self::form('report','analytics'); self::select('report_provider','Source',['gsc'=>'Google Search Console','ga'=>'Google Analytics 4']); self::select('dimension','Report',['total'=>'Totals','date'=>'Daily rows','query'=>'GSC: Queries','page'=>'GSC: Pages','country'=>'Country','device'=>'GSC: Device','sitemaps'=>'GSC: Sitemap status','sessionDefaultChannelGroup'=>'GA4: Acquisition','landingPage'=>'GA4: Landing pages','city'=>'GA4: Cities','deviceCategory'=>'GA4: Devices','organic'=>'GA4: Organic search']); self::select('period','Period',['all'=>'All Time (available)','yearly'=>'Last 365 days','quarterly'=>'Last 90 days','monthly'=>'Last 30 days','weekly'=>'Last 7 days','daily'=>'Today','custom'=>'Custom'],'all'); self::field('start','Custom start','','date'); self::field('end','Custom end','','date'); self::check('refresh','Refresh cached report'); self::end('Get report'); echo '</div>'; }
    private static function test_form(string $test,string $tab,string $label): void {
        self::form('test',$tab); echo '<input type="hidden" name="test" value="'.esc_attr($test).'">';
        if ($test==='ai') { $s=Config::get(); self::select('ai_provider','Provider to test (no fallback)',AI::choices($s['ai_provider']),$s['ai_provider'],'ai_provider_test'); self::check('consent','I authorize a short test prompt to be sent to the selected AI provider. Provider fees may apply.'); }
        submit_button($label,'secondary'); echo '</form>';
    }
    private static function ai(): void { self::test_form('ai','ai','Test Content AI'); echo '<div class="lst-panel"><p>Uses the WordPress native AI Client and configured Connectors. No Leadstart account is required. The text and selected post content are sent to the configured provider only when you request generation. Do not enter secrets or private personal data. Results are suggestions, not automatically saved.</p>'; self::form('ai','ai'); $s=Config::get(); self::select('ai_provider','AI provider',AI::choices($s['ai_provider']),$s['ai_provider']); echo '<p class="description">Model: automatic. '.esc_html(!empty($s['ai_fallback'])?'Fallback is enabled for explicit provider selection.':'Fallback is disabled.').'</p>'; self::select('task','Task',AI::tasks()); self::field('post_id','Optional saved post ID','','number'); self::field('attachment_id','Optional local image attachment ID (alt text, max 4 MB)','','number'); echo '<p><label for="lst-ai-text">Input, question, visual description, or aggregate metrics</label><textarea id="lst-ai-text" name="text" class="large-text" rows="8"></textarea></p>'; self::check('consent','I authorize this content to be sent to the selected AI provider and, if enabled, one fallback provider. Provider fees may apply.'); self::end('Generate suggestion'); echo '</div>'; }
    private static function table(array $headers,array $rows): void { echo '<div class="lst-scroll"><table class="widefat striped"><thead><tr>'; foreach ($headers as $h) { echo '<th>'.esc_html((string)$h).'</th>'; } echo '</tr></thead><tbody>'; foreach ($rows as $row) { echo '<tr>'; foreach ($row as $v) { echo '<td>'.esc_html(is_scalar($v)?(string)$v:'').'</td>'; } echo '</tr>'; } echo '</tbody></table></div>'; if (!$rows) { echo '<p>No rows returned for this report.</p>'; } }
    public static function handle(): void {
        $method=isset($_SERVER['REQUEST_METHOD']) && is_string($_SERVER['REQUEST_METHOD'])?sanitize_text_field(wp_unslash($_SERVER['REQUEST_METHOD'])):'';
        if (!current_user_can('manage_options') || $method!=='POST') { wp_die('Access denied.','',['response'=>403]); } check_admin_referer('lst_seo_admin','lst_seo_admin_nonce'); $op=self::text('op'); $tab=self::text('tab','dashboard'); if (!isset(self::tabs()[$tab])) { $tab='dashboard'; } check_admin_referer('lst_seo_'.$op); $s=Config::get();
        switch ($op) {
            case 'credentials':
                $raw=self::google_input(); $bing=self::bing_input(); foreach ([$raw,$bing] as $credential) { if (is_wp_error($credential)) { self::flash($tab,$credential->get_error_message(),'error'); } }
                foreach (['google_json'=>[$raw,self::checked_input('clear_google')],'bing_key'=>[$bing,self::checked_input('clear_bing')]] as $name=>$entry) { if ($entry[0]!=='' || $entry[1]) { $r=Config::set_secret($name,$entry[1]?'':$entry[0]); if (is_wp_error($r)) { self::flash($tab,$r->get_error_message(),'error'); } } } self::flash($tab,'Credential settings saved.'); break;
            case 'settings':
                foreach (['indexnow','bing_fallback','meta','schema','ai','purge','use_excerpt'] as $k) { $s[$k]=self::checked_input($k); } $key=self::text('index_key'); if (!$key && $s['indexnow']) { $key=bin2hex(random_bytes(16)); } if ($key && !preg_match('/^[A-Za-z0-9-]{8,128}$/D',$key)) { self::flash($tab,'Invalid IndexNow key.','error'); } $s['index_key']=$key;
                $path=self::text('key_path'); if ($path && (!preg_match('~^[A-Za-z0-9_-]+(?:/[A-Za-z0-9_-]+)*\.txt$~D',$path) || str_contains($path,'..'))) { self::flash($tab,'Key path must be a relative .txt path.','error'); } $s['key_path']=$path;
                $s['google_limit']=max(1,min(100000,(int)self::text('google_limit','200'))); $s['gsc_property']=self::text('gsc_property'); if ($s['gsc_property'] && !Config::property_ok($s['gsc_property'])) { self::flash($tab,'Search Console property must match the site.','error'); } $s['ga_property']=self::text('ga_property'); if ($s['ga_property'] && !preg_match('/^[0-9]{1,20}$/D',$s['ga_property'])) { self::flash($tab,'Invalid GA4 property ID.','error'); } $s['report_start']=self::text('report_start'); if ($s['report_start']!=='' && (!Config::date_ok($s['report_start']) || $s['report_start']>gmdate('Y-m-d'))) { self::flash($tab,'Invalid report start date.','error'); } $s['report_start_manual']=$s['report_start']!==''; $previous_provider=$s['ai_provider']; $s['ai_provider']=self::text('ai_provider'); if ($s['ai_provider']!=='' && $s['ai_provider']!==$previous_provider && empty(AI::providers()[$s['ai_provider']])) { self::flash($tab,'Select a configured WordPress AI provider or Automatic.','error'); } $s['ai_fallback']=self::checked_input('ai_fallback');
                foreach (['google_auto','indexnow_auto'] as $k) { $s[$k]=self::choices_input($k,array_keys(self::post_types())); } $s['excerpt_types']=self::choices_input('excerpt_types',array_keys(GEO::types())); if (count($s['excerpt_types'])===count(GEO::types())) { $s['excerpt_types']=null; } update_option(Config::OPTION,$s,false); Config::rotate_cache(); self::flash($tab,'Settings saved.'); break;
            case 'geo':
                $s['geo']=self::checked_input('geo');
                $s['geo_navigation']=self::checked_input('geo_navigation'); $s['geo_cache']=self::checked_input('geo_cache');
                $s['geo_bots']=self::choices_input('geo_bots',array_keys(GEO::bots()));
                if ($s['geo'] && GEO::conflict()) { self::flash($tab,__('Disable the other llms.txt generator first.','leadstart-seo'),'error'); }
                $s['geo_types']=self::choices_input('geo_types',array_keys(GEO::types()));
                $s['geo_limit']=max(1,min(200,(int)self::text('geo_limit','50')));
                $s['geo_title']=wp_html_excerpt(self::text('geo_title'),200,'');
                $s['geo_description']=wp_html_excerpt(self::textarea('geo_description'),500,'');
                update_option(Config::OPTION,$s,false); GEO::clear_cache(); self::flash($tab,__('GEO settings saved.','leadstart-seo')); break;
            case 'geo_clear': GEO::clear_cache(); self::flash($tab,__('GEO candidate cache cleared.','leadstart-seo')); break;
            case 'schema': $map=[]; $fields=[]; foreach (self::post_types() as $k=>$obj) { $v=self::checked_input('defaults')?(Schema::defaults()[$k]??''):self::text('schema_'.$k); if (in_array($v,Schema::types(),true)) { $map[$k]=$v; } $f=self::mapping_input('fields_'.$k); if (is_wp_error($f)) { self::flash($tab,$obj->label.': '.$f->get_error_message(),'error'); } if ($f) { $fields[$k]=$f; } } $s['schema_map']=$map; $s['field_map']=$fields; update_option(Config::OPTION,$s,false); self::flash($tab,'Schema mapping saved.'); break;
            case 'submit': $input=self::urls_input(); if (is_wp_error($input)) { self::flash($tab,$input->get_error_message(),'error'); } $count=0;$errors=array_fill(0,$input['invalid'],'Invalid URL, provider or action.'); foreach ($input['urls'] as $url) { $r=Queue::enqueue(self::text('provider'),self::text('request'),$url,0,self::checked_input('attest'),true); if (is_wp_error($r)) { $errors[]=$r->get_error_message(); } else { $count++; } } self::flash($tab,$count.' queued; '.count($errors).' rejected. '.implode(' ',array_unique($errors)),$errors?'warning':'success'); break;
            case 'run': Queue::work(); self::flash($tab,'Queue worker invoked. See History for results.'); break;
            case 'unlock': $ok=Queue::unlock(); self::flash($tab,$ok?'Stale lock released. Review unknown delivery records.':'No stale lock available.',$ok?'success':'error'); break;
            case 'retry': $ok=Queue::retry((int)self::text('id')); self::flash($tab,$ok?'Retry queued.':'Unable to retry.',$ok?'success':'error'); break;
            case 'report': $p=self::text('report_provider'); $d=self::text('dimension'); $range=Reports::range(self::text('period'),self::text('start'),self::text('end')); $r=Reports::get($p,$d,$range,self::checked_input('refresh')); if ($r['code']!==200 || !is_array($r['data'])) { self::flash($tab,'Report failed: '.$r['message'],'error'); } [$headers,$rows]=Reports::table($p,$d,$r); self::flash($tab,'Report returned. '.implode(' to ',$r['range']??$range),'success',['headers'=>$headers,'rows'=>$rows]); break;
            case 'ai': if (!self::checked_input('consent')) { self::flash($tab,'Consent is required.','error'); } $r=AI::run(self::text('task'),self::textarea('text'),(int)self::text('post_id'),(int)self::text('attachment_id'),self::text('ai_provider')); if (is_wp_error($r)) { self::flash($tab,$r->get_error_message(),'error'); } self::flash($tab,'AI suggestion generated. '.AI::result_label($r).' Review before using.','success',$r['text']); break;
            case 'test': $test=self::text('test'); if ($test==='google') { $t=API::token(API::INDEX_SCOPE); self::flash($tab,is_wp_error($t)?$t->get_error_message():'OAuth authentication succeeded (not proof of indexing permission).',is_wp_error($t)?'error':'success'); }
                if ($test==='indexnow') { $r=API::test_indexnow(); self::flash($tab,is_wp_error($r)?$r->get_error_message():'IndexNow public key test: HTTP 200. Key file matches. No URLs submitted.',is_wp_error($r)?'error':'success'); }
                if ($test==='ai') { if (!self::checked_input('consent')) { self::flash($tab,'Consent is required for the AI test prompt.','error'); } $r=AI::test(self::text('ai_provider')); self::flash($tab,is_wp_error($r)?$r->get_error_message():'Content AI test succeeded. '.AI::result_label($r).' No fallback used.',is_wp_error($r)?'error':'success'); }
                if ($test==='bing') { $r=API::bing_quota(); self::flash($tab,'Bing quota: '.$r['message'],$r['code']===200?'success':'error',$r['code']===200?wp_json_encode($r['data'],JSON_PRETTY_PRINT):null); }
                if (in_array($test,['gsc','ga'],true)) { $r=Reports::get($test,'total',Reports::range('weekly'),true); self::flash($tab,'Connection test: '.$r['message'],$r['code']===200?'success':'error'); } self::flash($tab,'Unknown test.','error'); break;
            default: self::flash($tab,'Invalid operation.','error');
        }
    }
    public static function bulk_hooks(): void { foreach (self::post_types() as $type=>$obj) { add_filter('bulk_actions-edit-'.$type,[self::class,'bulk_actions']); add_filter('handle_bulk_actions-edit-'.$type,[self::class,'bulk_handle'],10,3); } }
    public static function bulk_actions(array $actions): array { if (current_user_can('manage_options')) { $actions['lst_seo_google']='Leadstart: Google indexing'; $actions['lst_seo_indexnow']='Leadstart: IndexNow'; } return $actions; }
    public static function bulk_handle(string $redirect,string $action,array $ids): string { if (!in_array($action,['lst_seo_google','lst_seo_indexnow'],true) || !current_user_can('manage_options')) { return $redirect; } check_admin_referer('bulk-posts'); $n=0;$failed=0; foreach (array_slice($ids,0,100) as $id) { if (!current_user_can('edit_post',$id) || !($url=get_permalink($id))) { $failed++; continue; } $r=Queue::enqueue($action==='lst_seo_google'?'google':'indexnow','update',$url,(int)$id,false,true); if (is_wp_error($r)) { $failed++; } else { $n++; } } set_transient('lst_seo_flash_'.get_current_user_id(),['message'=>$n.' queued; '.$failed.' rejected. Maximum 100 per bulk action.','type'=>$failed?'warning':'success','data'=>null],120); return self::url('history'); }
}
